import heapq

def min_time_to_cross(n, m, safety_islands, g, r):
    safety_islands.sort()
    max_time = g + r
    visited = [[float('inf')] * (g + 1) for _ in range(m)]
    pq = [(0, 0, 0)]  # (time, island_index, remaining_green_time)
    visited[0][0] = 0

    while pq:
        time, island_index, remaining_green_time = heapq.heappop(pq)

        if island_index == m - 1:
            return time

        # Move to the next island or stay on the current island
        for next_island_index, next_island_pos in enumerate(safety_islands):
            if next_island_pos == safety_islands[island_index]:
                continue
            distance = abs(safety_islands[island_index] - next_island_pos)
            if remaining_green_time >= distance:
                if time + distance < visited[next_island_index][remaining_green_time - distance]:
                    visited[next_island_index][remaining_green_time - distance] = time + distance
                    heapq.heappush(pq, (time + distance, next_island_index, remaining_green_time - distance))
            else:
                if time + distance + g + r < visited[next_island_index][g - (distance - remaining_green_time)]:
                    visited[next_island_index][g - (distance - remaining_green_time)] = time + distance + g + r
                    heapq.heappush(pq, (time + distance + g + r, next_island_index, g - (distance - remaining_green_time)))

        # Change direction on the current island
        if remaining_green_time == 0:
            for direction in [-1, 1]:
                next_island_index = island_index
                next_island_pos = safety_islands[island_index] + direction
                if 0 <= next_island_pos < n:
                    next_island_index = safety_islands.index(next_island_pos)
